 "content": "def transform(grid):
    out = [row[:] for row in grid]
    markers = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    h, w = len(grid), len(grid[0])
    # A 5 with a nearby colored motif is the source anchor; isolated 5s are targets.
    def neighborhood(p):
        r, c = p
        return [(rr, cc, grid[rr][cc])
                for rr in range(max(0, r-4), min(h, r+5))
                for cc in range(max(0, c-4), min(w, c+5))
                if grid[rr][cc] not in (0, 5)]
    source = max(markers, key=lambda p: len(neighborhood(p)))
    motif = [(r-source[0], c-source[1], v) for r, c, v in neighborhood(source)]
    for target in markers:
        if target == source:
            continue
        tr, tc = target
        for dr, dc, v in motif:
            rr, cc = tr+dr, tc+dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = v
        out[tr][tc] = 0
    return out
